draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw plum
  ctx.fillStyle = 'plum';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50 + 20 * Math.sin(t), 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw antioxidant symbol
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.moveTo(W/2 + 70, H/2);
  ctx.lineTo(W/2 + 90, H/2 - 30);
  ctx.lineTo(W/2 + 90, H/2 + 30);
  ctx.lineTo(W/2 + 70, H/2);
  ctx.stroke();

  // draw stick figure
  ctx.lineWidth = 5;
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 50, 20, 0, 2 * Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 30);
  ctx.lineTo(W/2 - 100, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 70, H/2 - 20);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2);
  ctx.lineTo(W/2 - 70, H/2 + 20);
  ctx.stroke();

  ctx.restore();
}
